import React, {useState, type ReactNode, type CSSProperties} from 'react';
import './shell.css';
type Props = {workspace: ReactNode; inspector: ReactNode; section: string; onNavigate: (section: string) => void; inspectorWidth: number; onInspectorWidthChange: (width: number) => void};
export function ApplicationShell({workspace, inspector, section, onNavigate, inspectorWidth, onInspectorWidthChange}: Props) {
 const [navigationOpen, setNavigationOpen] = useState(false); const [inspectorOpen, setInspectorOpen] = useState(true);
 const width = Math.max(220, Math.min(480, inspectorWidth));
 return <div className="app-shell" style={{'--inspector-width': `${width}px`} as CSSProperties}>
 <a className="skip-link" href="#workspace">Skip to workspace</a>
 <header className="shell-toolbar"><strong>Workspace</strong><button className="nav-toggle" aria-expanded={navigationOpen} aria-controls="navigation" onClick={() => setNavigationOpen(!navigationOpen)}>Navigation</button><button aria-expanded={inspectorOpen} aria-controls="inspector" onClick={() => setInspectorOpen(!inspectorOpen)}>Inspector</button></header>
 <div className="shell-panes" data-inspector={inspectorOpen}>
 <nav id="navigation" className="shell-navigation pane" data-open={navigationOpen} aria-label="Workspace navigation" tabIndex={0}>{[{label: 'Workspace', items: ['Overview', 'Projects']}, {label: 'Organization', items: ['Members', 'Settings']}].map(group => <section key={group.label}><h2>{group.label}</h2>{group.items.map(item => <button key={item} aria-current={section === item ? 'page' : undefined} onClick={() => {onNavigate(item); setNavigationOpen(false);}}>{item}</button>)}</section>)}</nav>
 <main id="workspace" className="pane shell-workspace" tabIndex={-1} aria-label="Main workspace">{workspace}</main>
 <aside id="inspector" className="pane shell-inspector" hidden={!inspectorOpen} aria-label="Inspector" tabIndex={0}><h2>Inspector</h2><label className="inspector-size">Inspector width<input type="range" min={220} max={480} step={10} value={width} onChange={event => onInspectorWidthChange(Number(event.target.value))}/></label>{inspector}</aside>
 </div></div>;
}
// The application owns selected section, domain data, width and persistence.
